// Progress Bar Helper
function updateProgressBar(current, total) {
    const bar = document.getElementById('progressBarFill');
    if (bar && total > 0) {
        const percent = Math.max(0, Math.min(100, (current / total) * 100));
        bar.style.width = percent + '%';
    }
}

